# Direction copy. Each: key, name, take (one line), pitch, refs, concrete{}, ui{}, same_game, pipeline(level, text), risks
DIRS = [
dict(key='d1', name='Paper Theatre', take='Everything is cut paper on a stage: the best fit for cohesion, 124 px and code-drawn UI. My pick.',
 refs=['parappa','lammy','pm_ttyd1','pm_splash','spm','katamari','tearaway','yarn'],
 pitch='A puppet-show city. The pizzas are cardstock standees with two dot eyes and a hinged mouth, the streets are painted flats slid past on rails, and the cheese has a slight paper bevel. The warm silliness of PaRappa and Paper Mario carries the birthday-present tone, and the story lands because the faces are so simple that a small eyebrow change reads as heartbreak. The conspiracy thread is native: a corkboard is already paper pinned to paper, so it is the same material as the rest of the game.',
 concrete=dict(
  faces='One formula for everyone: two black dot eyes with one white glint, a small U or flat mouth, a rosy cheek disc. Species and role come from silhouette, brow and mustache only. The Old Timer is the same face with a bushy angry mustache shape and a police-hat cutout.',
  outlines='No heavy outline. A thin white die-cut sticker edge (2 px) around every character and interactive prop, plus a flat drop shadow of the same shape. Backgrounds have no edge at all.',
  palette='Candy-flat, 5 to 6 colours per asset, no gradients inside shapes. City tint per background: NY lavender and brick, Chicago steel blue, DC cream and sage, Naples terracotta and teal, Long Beach sand and turquoise. Hero cheese yellow and pepperoni red stay the loudest values.',
  depth='Background flats are pastel, low-contrast, and unshadowed (the exact opposite of the foreground standee look). Far layer: 3 pale tones. Mid layer: flat shapes with 1 tone of shadow. Near layer: translucent cut-paper leaves and wires, never black. A background object cannot take a drop shadow; only things you can touch can.',
  customers='Cutout standees from stacked primitives: a body shape, a head disc, one signature prop and one stereotype hat or hair shape. Because all faces share the formula, a Brooklyn guy and a Naples nonna differ by silhouette and clothing pattern, not by rendering style.'),
 ui=dict(
  title='Cardstock logo letters on a pennant string, buttons are tabs on a card.',
  select='Pizza cutout on a spotlight disc; toppings are a grid of stickers; the cursor is a paper hand.',
  receipt='Zigzag-edged tear-off paper with a flat stamp; the only text is large and hand-lettered.',
  board='Corkboard of paper cards; Polaroids are paper squares with blurred bush cutouts framing the edges.',
  dialog='Speech cards with a torn tail; name tab is a folded corner.',
  hud='Heat is a paper thermometer strip; bites are literal bite shapes cut out of a paper slice; special is a paper dial.',
  map='A pop-up map: streets are strips of coloured paper, stops are pushpins.'),
 same_game='Yes, by construction. Every surface is the same material (paper) with the same shadow rule, so a menu cannot look like a different game from a street.',
 pipeline=('Medium', 'Flat shapes with simple faces are the easiest style for image models at 124 px, and sprites need almost no cleanup. To hold one face formula I would hand-draw about 12 keys (the 4 slices, Old Timer, and one customer/enemy each) and train a style LoRA on them; a Kontext-class edit model or Qwen-Image with that LoRA can then restyle the roster. UI is mostly code-drawn (CSS or canvas paper cards, procedural zigzag edges, procedural drop shadows). Backgrounds go through a flatten and posterise step in forge instead of the current soften step. Pizza code rig keeps working, just with flat fills and a new face drawn on top.'),
 risks='Reads as childish if the story beats are not played straight; flat colour at 124 px can feel thin next to the current painted pixels. The die-cut edge is another hand-tuned post step. Paper texture must stay subtle or the models will invent fibre noise.'),

dict(key='d2', name='Rubber Hose 1930', take='The most charming, the hardest: needs hand animation or a big model jump. Best treated as a spice, not the whole game.',
 refs=['cuphead_art','cuphead_game','boop','willie','felix','gulliver','fiddlesticks'],
 pitch='A lost reel from 1931 in which the slices are tired mascots. Everything bends, everything has a pulse, the whole screen has film grain and a vignette. White-gloved noodle-limbed slices run through painted watercolour streets. The grizzled old slice with a police hat and angry mustache is pure Fleischer sourpuss, and the conspiracy board becomes an old newsreel title card. It would make a gorgeous trailer and a very distinctive game.',
 concrete=dict(
  faces='Pie-cut eyes (black oval with a wedge of white), a bean mouth, a button nose or none. Same for everyone: the Old Timer gets droopy lids and a handlebar mustache, nothing else changes. Every pizza wears white gloves.',
  outlines='One thick inked line (4 px at stage scale) on characters, pressure-varying, and a thinner brown line on background objects. Foreground is ink-black outline; background is ink-less watercolour.',
  palette='Sepia cream paper, ink black, a red, a yellow, a muted blue. Grain over everything. Cities are tinted washes only, not different palettes.',
  depth='Backgrounds are watercolour washes with soft edges, desaturated and low-contrast; characters are the only inked things. Plants and storefronts are never inked.',
  customers='Rubber-hose people with circle hands and pie eyes. A big Chicago man is a pear on stick legs; a Naples nonna is a bun in a shawl. Stereotypes are shapes first; this is where the 1930s edge is most dangerous, so keep them affectionate.'),
 ui=dict(
  title='A vintage title card with ornate double border and a bouncing logo.',
  select='Poster-like cast portraits in oval frames; hand-pointing glove as cursor.',
  receipt='A yellowed ticket with a red stamp; type is slab serif.',
  board='Newsreel clippings and photos with tape; Polaroids become grainy snapshots with vignette.',
  dialog='Silent-movie intertitle cards, optionally with a decorative border.',
  hud='Heat is a thermometer drawn as a bendy tube; bites are cartoon bite marks in the pie face.',
  map='An aged road map with a hand-inked route.'),
 same_game='Yes if grain, vignette and the intertitle border are applied as a global shader; without that, UI and sprites drift apart quickly.',
 pipeline=('Hard', 'Models are bad at consistent noodle limbs at 124 px (the current run cycle already fights splayed legs). It needs hand-drawn or rigged key poses for the 4 slices, a LoRA trained on rubber-hose data, and a code rig for run/jump so limbs keep their shape. Backgrounds as watercolour are feasible with an SDXL or Qwen-Image LoRA. The grain and vignette are one shader and cost almost nothing. Expect more hand-drawn work than any other direction.'),
 risks='Animation expense: rubber hose depends on motion, and 4 frames can make it look wrong. 1930s caricature of Italians and others needs care. Muted palette might reduce the hero pop.'),

dict(key='d3', name='Nicktoon Grotesque', take='Funniest faces, highest risk of looking sloppy at 124 px. Great for customers and sewer mutants, too wild for the heroes.',
 refs=['rocko','heffer','bev','spunky','filburt','rocko_concept','realmonsters','wolverton'],
 pitch='The slices are weirdos in a mean, funny city. Every face is slightly wrong in a loving way: popped eyes, huge gums, sweaty brow. Backgrounds are wonky, warped storefronts in a sick-pastel palette. Customers become the stars: one grotesque close-up per delivery, like a Ren and Stimpy zoom. The conspiracy board is a nervous Rocko-style collage and the sewer mutants finally look like they belong.',
 concrete=dict(
  faces='One formula: oversized white eyes with tiny pupils, a heavy lid line, a big lopsided mouth with a visible tooth row. Heroes are the cute end of the formula (round, small teeth); customers are the extreme end (same parts, bigger and asymmetric). Old Timer: scowl brow, bristly mustache like a pushbroom.',
  outlines='Variable black outline, thick on silhouettes, wobbly, with blots; interior lines thinner. Same wobble on everything, including UI.',
  palette='Mid-90s sick pastels: mustard, teal, bubblegum pink, swamp green, bruise purple. City palettes are hue-shifted, not redesigned.',
  depth='Backgrounds are flat painted shapes with no outline weight and a warm-grey cast; objects tilt but have no shadow. Foreground gets a thick outline; background none.',
  customers='This is the direction\'s best idea: customers are caricatures with huge hands and noses. Needs a very careful, affectionate line so the stereotypes are about the outfit and attitude, not the ethnicity.'),
 ui=dict(
  title='A lumpy blob logo with wobbly outlines; buttons are slime-shaped.',
  select='Rubbery portraits that squash when selected; the cursor is a cartoon hand.',
  receipt='Crooked receipt with scribbled handwriting and coffee stains.',
  board='Messy collage, taped photos at odd angles; Polaroids with fingerprints and blur.',
  dialog='Hand-lettered speech blobs with wobbly tails; shouted words are drawn bigger.',
  hud='Heat is a bubbling gauge; bites appear on the face with squishy tooth marks.',
  map='A hand-drawn doodle map with scribbled arrows.'),
 same_game='Yes, because wobble and blotchy outline apply to type, boxes and sprites alike; the weakest link is that wobble must be generated procedurally to stay consistent.',
 pipeline=('Hard', 'Models give grotesque faces willingly, but not the same grotesque face twice, and at 124 px detailed teeth and veins turn to noise. It needs a LoRA trained on a hand-drawn model sheet (the Rocko concept sheet is the shape of what we would draw) plus a face-template overlay (draw the eyes/mouth in code, as the pizzas already do). Wobbly outline can be a shader applied to every layer.'),
 risks='Grotesque can slide into ugly in the wrong hands. Customer caricature of five cities requires sensitivity. Rough line quality fights the pixel-snapped pipeline in STYLE.md.'),

dict(key='d4', name='Flash Vector', take='Cheapest cohesive option and totally code-drawable, but the least emotional. Great for the UI layer, thin for a birthday story.',
 refs=['strongbad','dexter','zim','mcboing'],
 pitch='A Newgrounds-era cartoon: clean vector shapes, uniform outlines, bright flat colour, a menu that looks like a goofy computer. The slices are bold geometric mascots; the world is simple graphic skylines. It feels like a game made by someone who loved Homestar Runner and Dexter\'s Lab. The conspiracy corkboard is a clicky desktop with pop-up windows.',
 concrete=dict(
  faces='Two oval eyes with black dot pupils, an arc mouth, a brow line. Eyes and mouth are the same vector parts on everyone; only proportions change. Old Timer: a thick brow and a rectangular mustache.',
  outlines='Uniform 3 px black stroke on everything, rounded joins. Backgrounds drop the stroke.',
  palette='Saturated flat fills, one highlight tone per shape; gradients only in sky. Four city palettes, each a hue family.',
  depth='Background shapes are fill-only (no outline), lighter and slightly desaturated; atmospheric gradient from the horizon. Foreground has the stroke.',
  customers='Geometric stereotypes: a rectangle man with a hat, a triangle woman with big hair. Fast to produce, easy to make 14 customers consistent.'),
 ui=dict(
  title='A bright start screen with beveled buttons and a logo with a hard drop shadow.',
  select='A flat character grid with big pizza art right; selected cell blinks.',
  receipt='A tidy vector receipt with a barcode.',
  board='A desktop-style board with windows and pins; Polaroids are low-fi photos in frames.',
  dialog='Clean rounded boxes with a speaker tab.',
  hud='Flat gauges and counters, simple icons.',
  map='A clean transit-style map with coloured routes.'),
 same_game='Yes, and it is the easiest to guarantee, because all of it can be generated from one set of vector rules.',
 pipeline=('Easy to Medium', 'Characters and UI can be drawn as vector (SVG) in code or by an SVG-oriented model, then rasterised at 124 px; the pizza rig already works this way. Image models are okay at this style with a LoRA but tend to add gradients. Hand-drawn keys are light: about 4 to 6.'),
 risks='Can look generic and corporate: the very complaint ("too generic") Tommy already has. Less emotional range for the story under the silliness.'),

dict(key='d5', name='Case File Noir', take='Strongest identity for the conspiracy and Dispatch tone, and a post-process look that unifies any model output. Best runner-up, or a UI/world layer on Paper Theatre.',
 refs=['sincity','spiderverse','sly','dispatch_tree','dispatch_poster','jsr','murderboard'],
 pitch='The slices are undercover operatives in a city that is mostly shadow, ink and halftone. Every screen is a page from a case file: manila folders, typewriter type, red stamps, string on a board. Heroes are the only fully colourful things, in flat cheesy yellow and pepperoni red; the rest of the world is a two-tone newsprint print with one red accent. The silliness hits harder because the frame is so serious.',
 concrete=dict(
  faces='One formula: heavy brow, half-lidded white eyes with a dot pupil, a flat mouth, and a hard black shadow shape across one side of the face. Heroes are same formula with lids raised. The Old Timer: lids low, brow down, an enormous mustache, a flat police hat.',
  outlines='Ink-black outline, 3 px at stage scale on characters; background objects are drawn in tone, no outline. Hard-edge shadow shapes instead of gradients.',
  palette='Ink black, newsprint cream, a deep blue-violet for night, one signal red. Heroes carry the only yellow. Each city gets one tinted overlay instead of a palette.',
  depth='The halftone does the depth work: far layers are fine low-contrast dots in a light tone, mid layers are coarser, near layers are solid ink shapes. Objects behind characters are always lighter than them.',
  customers='Newspaper-photo style caricatures: heavy ink faces under hats, each with a single colour accent. Because customers are mostly black-and-cream, they cannot look "AI-generated colourful".'),
 ui=dict(
  title='Folder cover with a stamped logo, buttons as index tabs.',
  select='A suspect-lineup page: portraits stuck to the folder, stats as typewritten fields.',
  receipt='A thermal receipt with a red CLASSIFIED stamp.',
  board='A conspiracy board, the real thing: cork, string, blurred Polaroids shot through leaves, sticky notes.',
  dialog='Typewriter caption boxes like Dispatch choices.',
  hud='A dossier strip: heat as a red ink bar, bites as ink bite marks, special as a stamp dial.',
  map='A black-and-white city map with a red route line.'),
 same_game='Yes. The folder/typewriter/halftone system also tells the story, and it works everywhere including cutscenes.',
 pipeline=('Medium', 'The look is mostly post-processing: a forge step that converts backgrounds to duotone plus halftone (code), and characters stay flat colour plus ink. That hides inter-image differences better than any other option. Needs a LoRA (or a stronger edit model) for the one face formula, about 12 hand-drawn keys, and the UI is entirely code-drawn paper and type. Halftone dots at 124 px get muddy, so use halftone only on large surfaces.'),
 risks='Dark mood may fight the silliness, and halftone on small sprites can look dirty. More post-processing code to maintain. Contrast with pixel snapping: the current pipeline expects 40 to 64 colours.'),

dict(key='d6', name='Arcade Pixel Cartoon', take='Lowest-risk upgrade of what exists; fits 124 px best, but will not by itself fix "generic AI".',
 refs=['wario4','shantae','scott','tmnt','sor2','metalslug','sunset','smrpg'],
 pitch='The game as a lost Konami arcade cabinet and a Pizza Runner GBA cart in one: fat outlines, sticker-bright palettes, big expressive faces, a fighting-game character select with a nameplate and bars, and a TMNT-style sewer. It keeps today\'s pipeline and tightens it: fewer colours, a fixed 32-colour master palette, hand-fixed faces.',
 concrete=dict(
  faces='A fixed pixel face template per size: two 3x4 px eyes with a 1 px white glint, a 2 px mouth, a 1 px brow, drawn by hand once and stamped (not generated). Old Timer: the same eyes with a flat brow and a big mustache sprite.',
  outlines='Heavy near-black violet outline, 2 px on stage, only on foreground. Background objects have no outline and sit in lighter palette steps.',
  palette='A shared 32-colour master palette; each city reuses it with a hue-shifted ramp. No colour exists outside the master palette, which enforces cohesion.',
  depth='Background objects are drawn with 2 value steps, 1 hue, no outline, and a lighter palette ramp than any foreground colour. This can be enforced by quantising each layer to its own ramp.',
  customers='Pixel stereotypes like Sunset Riders: one hat, one shirt, one prop each, hand-cleaned. The 14 customers are the best place to spend hand-cleaning time.'),
 ui=dict(
  title='A big pixel logo over a skyline, menu with blinking cursor.',
  select='A real Streets of Rage-style select: a grid of toppings and a big pizza portrait with a nameplate.',
  receipt='A pixel receipt in a mono pixel font.',
  board='A pixel corkboard; Polaroids are low-res, blurred, dithered snapshots with leaf borders.',
  dialog='9-slice boxes with a portrait, as in 16-bit RPGs.',
  hud='Hearts or a segmented heat bar, topping icon with counter, cooldown as a filling icon.',
  map='A 16-bit overworld map with path nodes.'),
 same_game='Yes. Pixel fonts, 9-slice boxes and one master palette hold every screen together, and the pipeline is already there.',
 pipeline=('Easy', 'It is basically the current pipeline with a locked palette and stamped face template. Use a stronger edit model for key poses, then quantise to the master palette. Hand-fixing 12 to 20 keys is the work. The sprite-forge keyer and soften step stay.'),
 risks='It may not fix "generic AI" and "no identity" complaints: it is a cleaner version of the same look. Painted-then-downsampled detail looks mushy at 124 px unless faces are stamped. Competes with the more distinctive options for identity.'),
]
